package com.stockpilot.service;
import com.stockpilot.entity.*; import com.stockpilot.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; import java.math.BigDecimal;
@Service public class WarehouseService {
 private final ProductRepository products; private final StockMovementRepository movements; private final CustomerOrderRepository orders;
 public WarehouseService(ProductRepository p,StockMovementRepository m,CustomerOrderRepository o){products=p;movements=m;orders=o;}
 public List<Product> allProducts(String q){return q==null||q.isBlank()?products.findAll():products.findByNameContainingIgnoreCaseOrSkuContainingIgnoreCase(q,q);}
 public Product product(Long id){return products.findById(id).orElseThrow(()->new NoSuchElementException("Product not found: "+id));}
 public Product create(Product p){if(products.existsBySku(p.getSku()))throw new IllegalArgumentException("SKU already exists.");return products.save(p);}
 public Product update(Long id,Product input){Product p=product(id);if(!p.getSku().equals(input.getSku())&&products.existsBySku(input.getSku()))throw new IllegalArgumentException("SKU already exists.");p.setName(input.getName());p.setSku(input.getSku());p.setCategory(input.getCategory());p.setReorderLevel(input.getReorderLevel());p.setUnitPrice(input.getUnitPrice());p.setLocation(input.getLocation());return products.save(p);}
 public void delete(Long id){Product p=product(id);if(movements.findAll().stream().anyMatch(m->m.getProduct().getId().equals(id)))throw new IllegalArgumentException("Product has stock history and cannot be deleted. Set quantity to zero instead.");products.delete(p);}
 @Transactional public Product changeStock(Long id,int quantity,String type,String note){if(quantity<=0)throw new IllegalArgumentException("Quantity must be greater than zero.");Product p=product(id);StockMovement.Type t;try{t=StockMovement.Type.valueOf(type.toUpperCase());}catch(Exception e){throw new IllegalArgumentException("Type must be STOCK_IN or STOCK_OUT.");}if(t==StockMovement.Type.ADJUSTMENT)throw new IllegalArgumentException("Use STOCK_IN or STOCK_OUT for this operation.");int next=t==StockMovement.Type.STOCK_IN?p.getQuantity()+quantity:p.getQuantity()-quantity;if(next<0)throw new IllegalArgumentException("Insufficient stock. Available: "+p.getQuantity());p.setQuantity(next);products.save(p);movements.save(new StockMovement(p,t,quantity,next,note));return p;}
 @Transactional public CustomerOrder createOrder(String customerName,List<Map<String,Object>> lines){if(customerName==null||customerName.isBlank())throw new IllegalArgumentException("Customer name is required.");if(lines==null||lines.isEmpty())throw new IllegalArgumentException("Add at least one order item.");CustomerOrder order=new CustomerOrder(customerName.trim());for(Map<String,Object> line:lines){Long productId=Long.valueOf(line.get("productId").toString());int qty=Integer.parseInt(line.get("quantity").toString());if(qty<=0)throw new IllegalArgumentException("Order quantity must be positive.");Product p=product(productId);if(p.getQuantity()<qty)throw new IllegalArgumentException("Insufficient stock for "+p.getName()+". Available: "+p.getQuantity());p.setQuantity(p.getQuantity()-qty);products.save(p);movements.save(new StockMovement(p,StockMovement.Type.STOCK_OUT,qty,p.getQuantity(),"Order fulfillment"));order.addItem(new OrderLine(p,qty));}order.setStatus(CustomerOrder.Status.COMPLETED);return orders.save(order);}
 public Map<String,Object> dashboard(){List<Product> all=products.findAll();int units=all.stream().mapToInt(Product::getQuantity).sum();BigDecimal value=all.stream().map(p->p.getUnitPrice().multiply(BigDecimal.valueOf(p.getQuantity()))).reduce(BigDecimal.ZERO,BigDecimal::add);return Map.of("totalProducts",all.size(),"totalUnits",units,"lowStockCount",all.stream().filter(p->p.getQuantity()<=p.getReorderLevel()).count(),"inventoryValue",value,"recentMovements",movements.findTop12ByOrderByCreatedAtDesc(),"recentOrders",orders.findTop10ByOrderByCreatedAtDesc());}
 public List<Product> lowStock(){return products.findAll().stream().filter(p->p.getQuantity()<=p.getReorderLevel()).toList();}
 public List<StockMovement> movements(){return movements.findTop12ByOrderByCreatedAtDesc();} public List<CustomerOrder> orders(){return orders.findTop10ByOrderByCreatedAtDesc();}
}